// Fungsinya menerima potongan teks dan nilainya SECARA TERPISAH.
function tebal(potongan, ...nilai) {
    return potongan.reduce(
        (hasil, teks, i) => hasil + teks + (i < nilai.length ? `**${nilai[i]}**` : ""),
        ""
    );
}

