function ambilData(id) {
    return new Promise((resolve, reject) => {
        setTimeout(() => {
            if (id > 0) {
                resolve(`Data-${id}`);        // berhasil
            } else {
                reject(new Error("ID tidak valid"));  // gagal
            }
        }, 1000);
    });
