class Rekening {
    #saldo;

    constructor(pemilik, saldo) {
        this.pemilik = pemilik;
        this.#saldo = saldo;
    }

    get saldo() {
        return this.#saldo;
    }

    setor(jumlah) {
        if (jumlah > 0) {
            this.#saldo += jumlah;
            return true;
        }
        return false;
    }

    tarik(jumlah) {
        if (jumlah > 0 && jumlah <= this.#saldo) {
            this.#saldo -= jumlah;
            return true;
        }
        return false;
    }
}

